// = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = =
// tcp_test —— Robonix TCP Server (v0.2)
//
// 职责：只负责 TCP 连接、收包、切帧、CRC 校验、应答；
//       不直接驱动运动。运动层保留在 Test POU。
//
// 协议帧：AA 55 | CMD(1) | LEN(2,LE) | SEQ(1) | PAYLOAD | CRC16(2,LE)
// CRC 覆盖 CMD..PAYLOAD（不含 SOF 和 CRC 自身）。
//
// 运动接口：
//   MotionSim = TRUE  : 当前只测 TCP，运动命令解析后立即 ACK；
//   MotionSim = FALSE : 等 Test 层把 MotionDone 置 TRUE 后再 ACK。
//   Test 层收到 MotionExecute 上升沿后应先置 MotionDone = FALSE，
//   运动完成/出错时再置 MotionDone / MotionError。
// ============================================================

CASE TCP_State OF

    // ========================================================
    // 0. 初始化
    // ========================================================
    0:
        TCPConnected := FALSE;
        TCPError := FALSE;

        AcceptExecute := FALSE;
        RcvExecute := FALSE;
        SendExecute := FALSE;
        CloseExecute := FALSE;
        StatusExecute := FALSE;

        Socket0 := 0;
        Socket1 := 0;

        RxLen := 0;
        RcvSize := 0;
        FrameReady := FALSE;
        FrameTotalLen := 0;
        PayloadStart := 0;
        SofPos := 0;
        PayloadLenU := 0;
        PayloadLenI := 0;
        TotalLenI := 0;

        CommandValid := FALSE;
        CmdIssued := FALSE;
        CommandDone := FALSE;
        CommandError := FALSE;

        MotionCmd := 0;
        MotionArg := FALSE;
        MotionExecute := FALSE;
        MotionError := FALSE;
        MotionErrorID := 0;
        MotionSeenBusy := FALSE;

        AckStatus := 0;
        AckError := 0;
        AckBusy := 0;
        AckPosition := FALSE;

        TCP_State := 10;

    // ========================================================
    // 10. 等待客户端连接
    // ========================================================
    10:
        AcceptExecute := TRUE;

        fbAccept(
            Execute := AcceptExecute,
            SrcTcpPort := 2000,
            TimeOut := 0,
            Done => Done,
            Busy => Busy,
            Error => Error,
            ErrorID => ErrorID,
            Socket0 => Socket0,
            Socket1 => Socket1
        );

        IF Done THEN
            AcceptExecute := FALSE;
            TCPConnected := TRUE;
            RxLen := 0;
            FrameReady := FALSE;
            TCP_State := 20;

        ELSIF Error THEN
            AcceptExecute := FALSE;
            TCPError := TRUE;
            TCP_State := 99;
        END_IF;

    // ========================================================
    // 20. 接收数据，追加到累积缓冲 RxAccum
    // = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = = =
    20 :
        IF FrameReady THEN
            TCP_State := 40;

        ELSIF RcvExecute THEN
            // ===== Phase TRUE：上升沿，真正读一次 socket =====
            fbRcv(
                Execute := TRUE,
                Socket0 := Socket0,
                TimeOut := 10,
                RcvData := ADR(RxBuffer[0]),
                Size := RxSize,
                Socket1 := Socket1,
                Done => Done,
                Busy => Busy,
                Error => Error,
                ErrorID => ErrorID,
                RcvSize => RcvSize
            );


            IF Done THEN
                RcvExecute := FALSE;      // 下一扫描给 FALSE，清 ExeLast
                
                IF RcvSize > 0 THEN
                    n := UINT_TO_INT(RcvSize);

                    IF (RxLen + n) > 4096 THEN
                        RxLen := 0;
                    END_IF;

                    IF n > 0 THEN
                        FOR i := 0 TO n - 1 DO
                            RxAccum[RxLen + i] := RxBuffer[i];
                        END_FOR;
                        RxLen := RxLen + n;
                    END_IF;

                    TCP_State := 30;      // 有数据，去解析
                ELSE
                    TCP_State := 20;      // 本次没数据，下一扫描继续轮询
                END_IF;

            ELSIF Error THEN
                RcvExecute := FALSE;
                TCPError := TRUE;
                TCP_State := 60;
            ELSIF Busy THEN
                // 引擎还在收：保持 Execute = TRUE，等它完成
                TCP_State := 20;
            ELSE
                RcvExecute := FALSE;
                TCP_State := 20;          // 没 Done，也回 20 继续轮询
            END_IF;

        ELSE
            // ===== Phase FALSE：让 FB 内部 ExeLast 清零 =====
            fbRcv(
                Execute := FALSE,
                Socket0 := Socket0,
                TimeOut := 10,
                RcvData := ADR(RxBuffer[0]),
                Size := RxSize,
                Socket1 := Socket1,
                Done => Done,
                Busy => Busy,
                Error => Error,
                ErrorID => ErrorID,
                RcvSize => RcvSize
            );

            RcvExecute := TRUE;
            TCP_State := 20;
        END_IF;

    // ========================================================
    // 30. 找 SOF、校验 LEN/CRC、切出一帧
    //     注意：帧先不消费，等 ACK 发送成功后再从缓冲移走
    // ========================================================
    30:
        IF FrameReady THEN
            TCP_State := 40;
        ELSE
            // 1) 查找帧头 AA 55
            SofPos := -1;
            IF RxLen >= 2 THEN
                FOR i := 0 TO RxLen - 2 DO
                    IF (RxAccum[i] = 16#AA) AND (RxAccum[i + 1] = 16#55) THEN
                        SofPos := i;
                        EXIT;
                    END_IF;
                END_FOR;
            END_IF;

            IF SofPos < 0 THEN
                // 没有帧头：只保留末尾可能的半个 SOF
                IF (RxLen >= 1) AND (RxAccum[RxLen - 1] = 16#AA) THEN
                    RxAccum[0] := RxAccum[RxLen - 1];
                    RxLen := 1;
                ELSE
                    RxLen := 0;
                END_IF;
                TCP_State := 20;

            ELSE
                // 2) 丢弃 SOF 之前的无效字节
                IF SofPos > 0 THEN
                    n := RxLen - SofPos;
                    IF n > 0 THEN
                        FOR i := 0 TO n - 1 DO
                            RxAccum[i] := RxAccum[i + SofPos];
                        END_FOR;
                    END_IF;
                    RxLen := n;
                END_IF;

                // 3) 至少要有 6 字节头 + 2 字节 CRC
                IF RxLen < 8 THEN
                    TCP_State := 20;
                ELSE
                    CMD := RxAccum[2];
                    PayloadLenU := USINT_TO_UDINT(RxAccum[3]);
                    CrcByte := USINT_TO_UDINT(RxAccum[4]);
                    PayloadLenU := PayloadLenU + CrcByte * 256;
                    SEQ := RxAccum[5];

                    IF PayloadLenU > 512 THEN
                        // LEN 非法：丢 1 字节，重新找 SOF
                        n := RxLen - 1;
                        IF n > 0 THEN
                            FOR i := 0 TO n - 1 DO
                                RxAccum[i] := RxAccum[i + 1];
                            END_FOR;
                        END_IF;
                        RxLen := n;
                        TCP_State := 30;

                    ELSE
                        PayloadLenI := UDINT_TO_INT(PayloadLenU);
                        TotalLenI := 8 + PayloadLenI;

                        IF RxLen < TotalLenI THEN
                            // 半包：等更多数据
                            TCP_State := 20;

                        ELSE
                            // 4) CRC16-Modbus，覆盖 CMD..PAYLOAD
                            CrcCalc := 16#FFFF;
                            FOR i := 2 TO 5 + PayloadLenI DO
                                CrcByte := USINT_TO_UDINT(RxAccum[i]);
                                CrcCalc := CrcCalc XOR CrcByte;
                                FOR b := 0 TO 7 DO
                                    IF (CrcCalc AND 16#0001) <> 0 THEN
                                        CrcCalc := (CrcCalc / 2) XOR 16#A001;
                                    ELSE
                                        CrcCalc := CrcCalc / 2;
                                    END_IF;
                                END_FOR;
                            END_FOR;

                            CrcRx := USINT_TO_UDINT(RxAccum[6 + PayloadLenI]);
                            CrcRxHi := USINT_TO_UDINT(RxAccum[6 + PayloadLenI + 1]);
                            CrcRx := CrcRx OR CrcRxHi * 256;

                            IF CrcCalc <> CrcRx THEN
                                // CRC 错：丢 1 字节，重新同步
                                n := RxLen - 1;
                                IF n > 0 THEN
                                    FOR i := 0 TO n - 1 DO
                                        RxAccum[i] := RxAccum[i + 1];
                                    END_FOR;
                                END_IF;
                                RxLen := n;
                                TCP_State := 30;

                            ELSE
                                // 5) 帧有效：记录位置，进入命令执行
                                PayloadStart := 6;   // SOF 已在 RxAccum[0..1]
                                FrameTotalLen := TotalLenI;
                                FrameReady := TRUE;
                                CommandValid := TRUE;
                                CmdIssued := FALSE;
                                CommandDone := FALSE;
                                CommandError := FALSE;
                                TCP_State := 40;
                            END_IF;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;

    // ========================================================
    // 40. 执行命令：解析载荷，置运动接口，等待完成
    // ========================================================
    40:
        IF NOT CmdIssued THEN
            CmdIssued := TRUE;

            AckStatus := 0;
            AckError := 0;
            AckBusy := BusyFlag;
            AckPosition := FALSE;

            CASE CMD OF

                // PING
                0x00 :
                    CommandDone := TRUE;

                // MOVE_LINEAR: x, y, z, vel = 4 x LREAL
                0x01 :
                    IF PayloadLenI >= 32 THEN
                        // 调用自定义函数 CopyBytes(dst, src, len)：把 8 字节原始数据
                        // 从接收缓冲搬到 LREAL，或从 LREAL 搬到发送缓冲。
                        // CopyBytes 在 CASS 的“子函数”窗口中定义，见工程说明。
                        FOR v := 1 TO 4 DO
                            Dummy := CopyBytes(dst := ADR(Params[v]), src := ADR(RxAccum[PayloadStart + (v - 1) * 8]), len := 8);
                        END_FOR;
                        TargetX := Params[1];
                        TargetY := Params[2];
                        TargetZ := Params[3];
                        TargetVel := Params[4];

                        MotionCmd := 1;
                        MotionArg := FALSE;
                        MotionExecute := TRUE;
                        IF MotionSim THEN
                            CommandDone := TRUE;
                        END_IF;
                    ELSE
                        AckStatus := 2;
                        AckError := 1;   // 载荷长度不足
                        CommandDone := TRUE;
                    END_IF;

                // HOME
                0x03 :
                    MotionCmd := 2;
                    MotionArg := FALSE;
                    MotionExecute := TRUE;
                    IF MotionSim THEN
                        CommandDone := TRUE;
                    END_IF;

                // SET_PARAM: vel, acc, dec, jerk, z_up, z_down = 6 x LREAL
                0x04 :
                    IF PayloadLenI >= 48 THEN
                        FOR v := 1 TO 6 DO
                            Dummy := CopyBytes(ADR(Params[v]), ADR(RxAccum[PayloadStart + (v - 1) * 8]), 8);
                        END_FOR;
                    ELSE
                        AckStatus := 2;
                        AckError := 1;
                    END_IF;
                    CommandDone := TRUE;

                // ENABLE: flag = U8
                0x05 :
                    IF PayloadLenI >= 1 THEN
                        MotionArg := RxAccum[PayloadStart] <> 0;
                        MotionCmd := 3;
                        MotionExecute := TRUE;
                        IF MotionSim THEN
                            CommandDone := TRUE;
                        END_IF;
                    ELSE
                        AckStatus := 2;
                        AckError := 1;
                        CommandDone := TRUE;
                    END_IF;

                // RESET
                0x06 :
                    MotionCmd := 4;
                    MotionArg := FALSE;
                    MotionExecute := TRUE;
                    IF MotionSim THEN
                        CommandDone := TRUE;
                    END_IF;

                // STOP
                0x07 :
                    MotionCmd := 5;
                    MotionArg := FALSE;
                    MotionExecute := TRUE;
                    IF MotionSim THEN
                        CommandDone := TRUE;
                    END_IF;

                // READ_STATUS
                0x08 :
                    AckBusy := BusyFlag;
                    CommandDone := TRUE;

                // GET_POSITION: ACK 载荷 25B = x,y,z (3 x LREAL) + busy
                0x09 :
                    AckBusy := BusyFlag;
                    AckPosition := TRUE;
                    CommandDone := TRUE;

                ELSE
                    AckStatus := 3;   // 未知命令
                    CommandDone := TRUE;

            END_CASE;
        END_IF;

        // 等运动层完成（MotionSim = TRUE 时上面已置 CommandDone）
        IF (NOT CommandDone) AND (NOT CommandError) THEN
            IF MotionError THEN
                CommandError := TRUE;
                AckStatus := 2;
                AckError := MotionErrorID;
            ELSIF (NOT MotionDone) THEN
                MotionSeenBusy := TRUE;
            ELSIF MotionSeenBusy AND MotionDone THEN
                CommandDone := TRUE;
            ELSIF MotionSim THEN
                CommandDone := TRUE;
            END_IF;
        END_IF;

        IF CommandDone OR CommandError THEN
            TCP_State := 50;
        END_IF;

    // ========================================================
    // 50. 组装并发送 ACK
    // ========================================================
    50 :
        IF AckPosition THEN
            // GET_POSITION: x, y, z, busy = 25B
            PayloadLenI := 25;
            PosCopy[1] := PosX;
            PosCopy[2] := PosY;
            PosCopy[3] := PosZ;
            FOR v := 1 TO 3 DO
                Dummy := CopyBytes(dst := ADR(TxBuffer[6 + (v - 1) * 8]), src := ADR(PosCopy[v]), len := 8);
            END_FOR;
            TxBuffer[30] := BusyFlag;
        ELSE
            // 普通 ACK: status(U8) + err(U16) + busy(U8) = 4B
            PayloadLenI := 4;
            TxBuffer[6] := AckStatus;
            TxBuffer[7] := UINT_TO_USINT(AckError MOD 256);
            TxBuffer[8] := UINT_TO_USINT(AckError / 256);
            TxBuffer[9] := AckBusy;
        END_IF;

        PayloadLength := INT_TO_UINT(PayloadLenI);
        TxSize := INT_TO_UINT(8 + PayloadLenI);

        TxBuffer[0] := 16#AA;
        TxBuffer[1] := 16#55;
        TxBuffer[2] := 16#80;            // CMD_ACK
        TxBuffer[3] := INT_TO_USINT(PayloadLenI);      // LEN 低字节
        TxBuffer[4] := INT_TO_USINT(PayloadLenI / 256);
        TxBuffer[5] := SEQ;

        // CRC 覆盖 CMD..PAYLOAD，即 TxBuffer[2 .. 5+LEN]
        CrcCalc := 16#FFFF;
        FOR i := 2 TO 5 + PayloadLenI DO
            CrcByte := USINT_TO_UDINT(TxBuffer[i]);
            CrcCalc := CrcCalc XOR CrcByte;
            FOR b := 0 TO 7 DO
                IF (CrcCalc AND 16#0001) <> 0 THEN
                    CrcCalc := (CrcCalc / 2) XOR 16#A001;
                ELSE
                    CrcCalc := CrcCalc / 2;
                END_IF;
            END_FOR;
        END_FOR;

        TxBuffer[6 + PayloadLenI] := UDINT_TO_USINT(CrcCalc MOD 256);
        TxBuffer[7 + PayloadLenI] := UDINT_TO_USINT(CrcCalc / 256);

        SendExecute := TRUE;
        fbSend(
            Execute := SendExecute,
            Socket0 := Socket0,
            SendData := ADR(TxBuffer[0]),
            Size := TxSize,
            Socket1 := Socket1,
            Done => Done,
            Busy => Busy,
            Error => Error,
            ErrorID => ErrorID
        );

        IF Done THEN
            SendExecute := FALSE;

            // 已 ACK，消费该帧
            n := RxLen - FrameTotalLen;
            IF n > 0 THEN
                FOR i := 0 TO n - 1 DO
                    RxAccum[i] := RxAccum[i + FrameTotalLen];
                END_FOR;
            END_IF;
            RxLen := n;

            FrameReady := FALSE;
            CommandValid := FALSE;
            CmdIssued := FALSE;
            CommandDone := FALSE;
            CommandError := FALSE;
            MotionExecute := FALSE;
            MotionSeenBusy := FALSE;
            AckPosition := FALSE;

            TCP_State := 30;   // 先处理缓冲里可能粘着的下一帧

        ELSIF Error THEN
            SendExecute := FALSE;
            TCPError := TRUE;
            TCP_State := 60;
        END_IF;

    // ========================================================
    // 60. 检查 TCP 连接状态
    // ========================================================
    60:
        StatusExecute := TRUE;
        fbStatus(
            Execute := StatusExecute,
            Socket0 := Socket0,
            Socket1 := Socket1,
            Done => Done,
            Busy => Busy,
            Error => Error,
            ErrorID => ErrorID,
            TCPStatus => TCPStatusVal,
            DatRcvFlag => DatRcvFlagVal
        );

        IF Done THEN
            StatusExecute := FALSE;
            TCP_State := 20;
        ELSIF Error THEN
            StatusExecute := FALSE;
            TCP_State := 90;
        END_IF;

    // ========================================================
    // 90. 关闭连接
    // ========================================================
    90:
        CloseExecute := TRUE;

        fbClose(
            Execute := CloseExecute,
            Socket0 := Socket0,
            Socket1 := Socket1,
            Done => Done,
            Busy => Busy,
            Error => Error,
            ErrorID => ErrorID
        );

        IF Done OR Error THEN
            CloseExecute := FALSE;
            TCPConnected := FALSE;
            RxLen := 0;
            FrameReady := FALSE;
            TCP_State := 0;
        END_IF;

    // ========================================================
    // 99. 致命错误
    // ========================================================
    99:
        AcceptExecute := FALSE;
        RcvExecute := FALSE;
        SendExecute := FALSE;
        StatusExecute := FALSE;
        TCP_State := 90;

END_CASE;

END_PROGRAM

VarRoot.Var_Code:
PROGRAM tcp_test

VAR
    // ===== TCP 状态机 =====
    TCP_State : INT := 0;
    LastTCP_State : INT := -1;

    // ===== TCP 功能块 =====
    fbAccept : SktTCPAccept;
    fbRcv : SktTCPRcv;
    fbSend : SktTCPSend;
    fbClose : SktTCPClose;
    fbStatus : SktGetTCPStatus;

    // ===== Socket 句柄 =====
    Socket0 : UDINT := 0;
    Socket1 : UDINT := 0;

    // ===== TCP 功能块控制 =====
    AcceptExecute : BOOL := FALSE;
    RcvExecute : BOOL := FALSE;
    SendExecute : BOOL := FALSE;
    CloseExecute : BOOL := FALSE;
    StatusExecute : BOOL := FALSE;

    // ===== TCP 状态 =====
    TCPConnected : BOOL := FALSE;
    TCPError : BOOL := FALSE;
    TCPStatusVal : UINT := 0;
    DatRcvFlagVal : BOOL := FALSE;

    // ===== 接收缓冲区 =====
    RxBuffer : ARRAY[0..2047] OF USINT;
    RxSize : UINT := 2048;
    RcvSize : UINT := 0;
    RxAccum : ARRAY[0..4095] OF USINT;
    RxLen : INT := 0;

    // ===== 发送缓冲区 =====
    TxBuffer : ARRAY[0..255] OF USINT;
    TxSize : UINT := 0;

    // ===== 协议解析 =====
    FrameLength : UINT := 0;
    PayloadLength : UINT := 0;
    CMD : USINT := 0;
    SEQ : USINT := 0;
    PayloadStart : INT := 0;
    PayloadLenU : UDINT := 0;
    PayloadLenI : INT := 0;
    TotalLenI : INT := 0;
    FrameReady : BOOL := FALSE;
    FrameTotalLen : INT := 0;
    SofPos : INT := 0;
    CrcCalc : UDINT := 0;
    CrcRx : UDINT := 0;
    CrcByte : UDINT := 0;
    CrcRxHi : UDINT := 0;
    Dummy : BOOL := FALSE;   // CopyBytes 的返回值
    i : INT := 0;
    b : INT := 0;
    n : INT := 0;
    v : INT := 0;

    // ===== 应答 =====
    AckStatus : USINT := 0;
    AckError : UINT := 0;
    AckBusy : USINT := 0;
    AckPosition : BOOL := FALSE;

    // ===== 功能块输出 =====
    Done : BOOL;
    Busy : BOOL;
    Error : BOOL;
    ErrorID : UINT;

    // ===== 数据处理 =====
    NewFrame : BOOL := FALSE;
    CommandValid : BOOL := FALSE;
    CmdIssued : BOOL := FALSE;

    // ===== 运动层接口（Test POU 读写） =====
    MotionCmd : INT := 0;
    MotionArg : BOOL := FALSE;
    MotionExecute : BOOL := FALSE;
    MotionDone : BOOL := TRUE;
    MotionError : BOOL := FALSE;
    MotionErrorID : UINT := 0;
    MotionSim : BOOL := TRUE;
    MotionSeenBusy : BOOL := FALSE;

    // ===== 运动参数 / 位置 =====
    TargetX : LREAL;
    TargetY : LREAL;
    TargetZ : LREAL;
    TargetVel : LREAL;
    Params : ARRAY[1..6] OF LREAL;
    PosCopy : ARRAY[1..3] OF LREAL;
    PosX : LREAL := 0;
    PosY : LREAL := 0;
    PosZ : LREAL := 0;
    BusyFlag : USINT := 0;

    // ===== 命令执行状态 =====
    CommandDone : BOOL := FALSE;
    CommandError : BOOL := FALSE;
END_VAR

VAR_INPUT

END_VAR

VAR_OUTPUT

END_VAR

VAR_CONSTANT

END_VAR
